<script setup lang="ts">
import {ref,onMounted,onBeforeUnmount,watch} from 'vue';import {useRouter} from 'vue-router';import axios from 'axios';import CodeEditor from '../components/CodeEditor.vue';import {installAntiCheat} from '../utils/antiCheat'
const router=useRouter();const identity=localStorage.getItem('username')||'考生';const logout=()=>{localStorage.clear();router.replace('/login')};const examId='demo';const question=ref<any>({id:'',title:'正在加载题目…'});const code=ref('');const version=ref(0);const saved=ref('尚未保存');const output=ref('');const remaining=ref(0);let timer:any,stopCheat:()=>void
async function load(){const r=await axios.get(`/api/v1/exams/${examId}`);question.value=r.data.questions[0];const d=await axios.get(`/api/v1/exams/${examId}/questions/${question.value.id}/draft`);code.value=d.data.code;version.value=d.data.version;remaining.value=r.data.remaining_seconds||0}async function save(){saved.value='正在自动保存...';const r=await axios.put(`/api/v1/exams/${examId}/questions/${question.value.id}/draft`,{code:code.value,version:version.value});version.value=r.data.version;saved.value=`草稿已同步至云端（版本号: v${version.value}） · 最后保存时间：${new Date().toLocaleTimeString()}`}let debounce:any;watch(code,()=>{clearTimeout(debounce);debounce=setTimeout(save,2000)});async function sample(){const r=await axios.post(`/api/v1/exams/${examId}/questions/${question.value.id}/run-sample`,{code:code.value});output.value=`执行结果：已加入样例调试队列（${r.data.sample_cases} 个样例）`}async function submit(){if(confirm('确定要提交整套试卷吗？交卷后试卷将立即锁定，不可再修改代码或调试，系统将对全卷进行正式机器判题。'))await axios.post(`/api/v1/exams/${examId}/submit`,{confirm:true})}onMounted(async()=>{await load();stopCheat=installAntiCheat(examId);timer=setInterval(()=>{if(remaining.value>0)remaining.value--},1000)});onBeforeUnmount(()=>{stopCheat?.();clearInterval(timer);clearTimeout(debounce)})
</script>
<template><main><header><h1>LabProctor OJ - 在线考试系统</h1><div>考生：{{identity}} <button @click="logout">退出登录</button><br>考试剩余时间：{{String(Math.floor(remaining/3600)).padStart(2,'0')}}:{{String(Math.floor(remaining/60)%60).padStart(2,'0')}}:{{String(remaining%60).padStart(2,'0')}}<small>（服务端基准时钟同步）</small></div></header><section><aside><h2>题目列表</h2><h3>第 1 题：{{question.title}}</h3><p>{{question.statement}}</p><p>满分：{{question.max_score||0}} 分</p><p>时间限制：{{question.time_limit_ms||0}} ms</p><p>内存限制：{{question.memory_limit_kb||0}} MB</p><p class="tip">提示：灰色区域为教师预设模板框架，不可修改；请在指定区域编写您的代码</p><button @click="sample">▶ 运行样例调试（不计入成绩）</button><p>{{saved}}</p><h3>调试输出面板</h3><pre>{{output||'执行结果：等待样例调试'}}</pre></aside><article><CodeEditor v-model="code" /></article></section><footer><button @click="save">立即保存草稿</button><button class="submit" @click="submit">整套试卷交卷</button></footer></main></template>
<style scoped>main{font:14px system-ui;background:#f5f7fb;min-height:100vh;padding:20px}header,footer{display:flex;justify-content:space-between;align-items:center;background:white;padding:12px 20px;border-radius:8px}small{display:block;color:#667085;font-weight:normal}section{display:grid;grid-template-columns:30% 70%;gap:12px;margin:12px 0}aside{background:white;padding:16px;border-radius:8px}.tip{background:#f0f0f0;padding:10px;color:#475467}button{padding:8px 14px;border:0;border-radius:5px;cursor:pointer}.submit{background:#b42318;color:white}pre{white-space:pre-wrap;background:#111;color:#9fe870;padding:10px}</style>
